// Auto-generated 1200x630 OpenGraph PNG & JPEG images for social media previews (WhatsApp, Telegram, Facebook, Twitter)
const OG_IMAGE_PNG_BASE64 = "";
const OG_IMAGE_JPEG_BASE64 = "";

function decodeBase64(base64: string): Uint8Array {
  if (typeof Buffer !== "undefined") {
    return Buffer.from(base64, "base64");
  }
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

export const OG_IMAGE_PNG: Uint8Array = decodeBase64(OG_IMAGE_PNG_BASE64);
export const OG_IMAGE_JPEG: Uint8Array = decodeBase64(OG_IMAGE_JPEG_BASE64);
